// Java-Code der Instanz zu „Prototype“, unverändert aus der Lieferung – geschrieben von skripte/pattern-einlesen.pl, nicht von Hand ändern
window.MUSTER_CODE = ["// Prototype (GoF, Erzeugungsmuster)","// Neue Objekte entstehen durch Kopieren eines vorhandenen Prototyps statt durch \"new\".","// Start: java Prototype.java","","import java.util.ArrayList;","import java.util.HashMap;","import java.util.List;","import java.util.Map;","","public class Prototype {","","    // --- Prototype: jedes Objekt kann sich selbst kopieren ---","    interface Form {","        Form kopie();","        void verschiebe(int dx, int dy);","    }","","    // --- Konkrete Prototypen (veränderlich, deshalb lohnt sich das Kopieren) ---","    static final class Kreis implements Form {","        int x, y, radius;","        String farbe;","","        Kreis(int x, int y, int radius, String farbe) {","            this.x = x; this.y = y; this.radius = radius; this.farbe = farbe;","        }","","        // Kopierkonstruktor statt clone()","        private Kreis(Kreis vorlage) {","            this(vorlage.x, vorlage.y, vorlage.radius, vorlage.farbe);","        }","","        public Kreis kopie() { return new Kreis(this); }","        public void verschiebe(int dx, int dy) { x += dx; y += dy; }","        public String toString() {","            return \"Kreis(\" + x + \",\" + y + \" r=\" + radius + \" \" + farbe + \")\";","        }","    }","","    static final class Rechteck implements Form {","        int x, y, breite, hoehe;","","        Rechteck(int x, int y, int breite, int hoehe) {","            this.x = x; this.y = y; this.breite = breite; this.hoehe = hoehe;","        }","","        private Rechteck(Rechteck vorlage) {","            this(vorlage.x, vorlage.y, vorlage.breite, vorlage.hoehe);","        }","","        public Rechteck kopie() { return new Rechteck(this); }","        public void verschiebe(int dx, int dy) { x += dx; y += dy; }","        public String toString() {","            return \"Rechteck(\" + x + \",\" + y + \" \" + breite + \"x\" + hoehe + \")\";","        }","    }","","    // --- Zusammengesetzter Prototyp: braucht eine TIEFE Kopie ---","    static final class Gruppe implements Form {","        final String name;","        final List<Form> teile = new ArrayList<>();","","        Gruppe(String name, Form... teile) {","            this.name = name;","            this.teile.addAll(List.of(teile));","        }","","        public Gruppe kopie() {","            Gruppe g = new Gruppe(name);","            for (Form f : teile) {","                g.teile.add(f.kopie());   // jedes Teil einzeln kopieren","            }","            return g;","        }","","        public void verschiebe(int dx, int dy) {","            teile.forEach(f -> f.verschiebe(dx, dy));","        }","","        public String toString() { return name + teile; }","    }","","    // --- Prototyp-Registry: vorkonfigurierte Vorlagen unter einem Namen ---","    static final class Vorlagen {","        private final Map<String, Form> vorlagen = new HashMap<>();","","        void registriere(String name, Form vorlage) { vorlagen.put(name, vorlage); }","","        Form erzeuge(String name) {","            Form vorlage = vorlagen.get(name);","            if (vorlage == null) {","                throw new IllegalArgumentException(\"Unbekannte Vorlage: \" + name);","            }","            return vorlage.kopie();","        }","    }","","    public static void main(String[] args) {","        Vorlagen vorlagen = new Vorlagen();","        vorlagen.registriere(\"ampel-rot\", new Kreis(0, 0, 10, \"rot\"));","        vorlagen.registriere(\"schild\", new Gruppe(\"Schild\",","                new Rechteck(0, 0, 40, 20), new Kreis(20, 10, 5, \"weiß\")));","","        // Neue Objekte aus Vorlagen","        Form a = vorlagen.erzeuge(\"ampel-rot\");","        Form b = vorlagen.erzeuge(\"ampel-rot\");","        b.verschiebe(50, 0);","        System.out.println(\"a = \" + a);","        System.out.println(\"b = \" + b);","","        // Tiefe Kopie: Verschieben der Kopie lässt die Vorlage unberührt","        Form schild = vorlagen.erzeuge(\"schild\");","        schild.verschiebe(100, 100);","        System.out.println(\"Kopie:   \" + schild);","        System.out.println(\"Vorlage: \" + vorlagen.erzeuge(\"schild\"));","    }","}"];
